with w as(select *from public.works where id in(3310,3436,4176,3172,4976,3216))select jsonb_build_object('checked_at',clock_timestamp(),'works',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from w t),'authors',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from public.authors t where id in(select author_id from w)),'editions',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from public.editions t where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(t)order by work_id,language),'[]')from public.catalog_work_descriptions t where work_id in(select id from w)),'metadata',(select coalesce(jsonb_agg(to_jsonb(t)order by edition_id),'[]')from public.catalog_edition_metadata t where work_id in(select id from w)))as preflight;